 * Designer: Behnam (X Series / Irmug) — https://fontlibrary.org/en/font/xb-roya
 * Licensed under the SIL Open Font License, Version 1.1 — see LICENSE / OFL.txt.
 */

@font-face {
  font-family: "XB Roya";
  src: url("./XBRoya-Regular.woff2") format("woff2");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "XB Roya";
  src: url("./XBRoya-Bold.woff2") format("woff2");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "XB Roya";
  src: url("./XBRoya-Italic.woff2") format("woff2");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "XB Roya";
  src: url("./XBRoya-BoldItalic.woff2") format("woff2");
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}
